namespace UniversityCourseCatalog.Models;

public class Department
{
    public int Id { get; set; }
    public string Name { get; set; } = string.Empty;
    public string Abbreviation { get; set; } = string.Empty;
    public string Description { get; set; } = string.Empty;
}

namespace UniversityCourseCatalog.Models;

public class Course
{
    public int Id { get; set; }
    public int DepartmentId { get; set; }
    public string Code { get; set; } = string.Empty;
    public string Title { get; set; } = string.Empty;
    public string Description { get; set; } = string.Empty;
    public int Credits { get; set; }
    public string Schedule { get; set; } = string.Empty;
    public string InstructorName { get; set; } = string.Empty;
    public string InstructorBio { get; set; } = string.Empty;
    public bool IsFeatured { get; set; }
}

using System.ComponentModel.DataAnnotations;

namespace UniversityCourseCatalog.Models;

public class EnrollmentRequest
{
    [Required(ErrorMessage = "Name is required.")]
    [StringLength(100, ErrorMessage = "Name cannot exceed 100 characters.")]
    public string StudentName { get; set; } = string.Empty;

    [Required(ErrorMessage = "Student ID is required.")]
    [RegularExpression(@"^[A-Za-z0-9]{6,12}$", ErrorMessage = "Student ID must be 6–12 alphanumeric characters.")]
    public string StudentId { get; set; } = string.Empty;

    [Required(ErrorMessage = "Please select a course.")]
    [Range(1, int.MaxValue, ErrorMessage = "Please select a course.")]
    public int CourseId { get; set; }
}

using UniversityCourseCatalog.Models;

namespace UniversityCourseCatalog.Services;

public interface ICatalogService
{
    List<Department> GetDepartments();
    Department? GetDepartment(int id);
    List<Course> GetCourses(string? search = null, int? departmentId = null);
    List<Course> GetFeaturedCourses();
    Course? GetCourse(int id);
    List<Course> GetCoursesByDepartment(int departmentId);
    bool SubmitEnrollment(EnrollmentRequest request);
}

using UniversityCourseCatalog.Models;

namespace UniversityCourseCatalog.Services;

public class CatalogService : ICatalogService
{
    private readonly List<Department> _departments;
    private readonly List<Course> _courses;

    public CatalogService()
    {
        _departments = new List<Department>
        {
            new() { Id = 1, Name = "Computer Science", Abbreviation = "CS", Description = "Study of computation, algorithms, data structures, and software engineering principles." },
            new() { Id = 2, Name = "Mathematics", Abbreviation = "MATH", Description = "Exploration of abstract structures, quantities, and patterns through rigorous proof and analysis." },
            new() { Id = 3, Name = "Physics", Abbreviation = "PHYS", Description = "Investigation of matter, energy, and the fundamental forces governing the natural world." },
            new() { Id = 4, Name = "English", Abbreviation = "ENG", Description = "Critical analysis of literature, rhetoric, and the craft of written communication." },
            new() { Id = 5, Name = "History", Abbreviation = "HIST", Description = "Examination of past civilizations, events, and cultural movements that shaped the modern world." },
        };

        _courses = new List<Course>
        {
            new() { Id = 1, DepartmentId = 1, Code = "CS 101", Title = "Introduction to Programming", Description = "Learn the fundamentals of programming using Python. Topics include variables, control flow, functions, and basic data structures. No prior experience required.", Credits = 3, Schedule = "Mon/Wed/Fri 9:00–9:50 AM", InstructorName = "Dr. Sarah Chen", InstructorBio = "Dr. Chen holds a Ph.D. in Computer Science from MIT and has 15 years of teaching experience. She specializes in programming pedagogy and has authored two textbooks on introductory computing.", IsFeatured = true },
            new() { Id = 2, DepartmentId = 1, Code = "CS 201", Title = "Data Structures and Algorithms", Description = "Study of fundamental data structures (lists, trees, graphs, hash tables) and algorithm design techniques (sorting, searching, dynamic programming). Prerequisite: CS 101.", Credits = 4, Schedule = "Tue/Thu 10:30 AM–12:00 PM", InstructorName = "Prof. James Park", InstructorBio = "Prof. Park is an ACM Distinguished Educator with research interests in algorithm optimization and competitive programming. He previously worked at Google Research.", IsFeatured = true },
            new() { Id = 3, DepartmentId = 1, Code = "CS 310", Title = "Database Systems", Description = "Design and implementation of relational databases. Covers SQL, normalization, indexing, transaction processing, and an introduction to NoSQL systems.", Credits = 3, Schedule = "Mon/Wed 2:00–3:20 PM", InstructorName = "Dr. Maria Rodriguez", InstructorBio = "Dr. Rodriguez specializes in distributed database systems and has published over 30 papers in top-tier venues. She consults for several Fortune 500 companies on data architecture." },
            new() { Id = 4, DepartmentId = 1, Code = "CS 450", Title = "Machine Learning", Description = "Introduction to machine learning concepts including supervised and unsupervised learning, neural networks, and model evaluation. Prerequisites: CS 201, MATH 210.", Credits = 4, Schedule = "Tue/Thu 1:00–2:30 PM", InstructorName = "Dr. Sarah Chen", InstructorBio = "Dr. Chen holds a Ph.D. in Computer Science from MIT and has 15 years of teaching experience. Her current research focuses on explainable AI and fairness in machine learning.", IsFeatured = true },
            new() { Id = 5, DepartmentId = 2, Code = "MATH 110", Title = "Calculus I", Description = "Limits, derivatives, and integrals of single-variable functions. Applications to physics, engineering, and economics.", Credits = 4, Schedule = "Mon/Wed/Fri 10:00–10:50 AM", InstructorName = "Dr. Robert Kim", InstructorBio = "Dr. Kim is an award-winning mathematics educator who has developed innovative visual approaches to teaching calculus. He holds a Ph.D. from Princeton University." },
            new() { Id = 6, DepartmentId = 2, Code = "MATH 210", Title = "Linear Algebra", Description = "Vector spaces, matrices, linear transformations, eigenvalues, and applications. Essential for advanced work in science and engineering.", Credits = 3, Schedule = "Tue/Thu 9:00–10:20 AM", InstructorName = "Prof. Lisa Wang", InstructorBio = "Prof. Wang's research bridges pure mathematics and data science. She is the recipient of the university's Excellence in Teaching Award for three consecutive years.", IsFeatured = true },
            new() { Id = 7, DepartmentId = 2, Code = "MATH 320", Title = "Probability and Statistics", Description = "Probability theory, random variables, distributions, hypothesis testing, and regression analysis. Applications across the sciences.", Credits = 3, Schedule = "Mon/Wed/Fri 1:00–1:50 PM", InstructorName = "Dr. Robert Kim", InstructorBio = "Dr. Kim is an award-winning mathematics educator with a secondary research focus on applied statistics and Bayesian methods." },
            new() { Id = 8, DepartmentId = 3, Code = "PHYS 101", Title = "General Physics I", Description = "Mechanics, thermodynamics, and waves. Includes weekly laboratory sessions. Co-requisite: MATH 110.", Credits = 4, Schedule = "Mon/Wed/Fri 11:00–11:50 AM + Thu Lab 2:00–4:50 PM", InstructorName = "Dr. Alan Foster", InstructorBio = "Dr. Foster is an experimental physicist with NASA research experience. He brings real-world applications to the introductory physics curriculum.", IsFeatured = true },
            new() { Id = 9, DepartmentId = 3, Code = "PHYS 201", Title = "General Physics II", Description = "Electricity, magnetism, optics, and modern physics. Includes weekly laboratory sessions. Prerequisite: PHYS 101.", Credits = 4, Schedule = "Tue/Thu 11:00 AM–12:30 PM + Fri Lab 2:00–4:50 PM", InstructorName = "Prof. Diana Okoro", InstructorBio = "Prof. Okoro's research in quantum optics has been published in Nature and Physical Review Letters. She is passionate about making physics accessible to all students." },
            new() { Id = 10, DepartmentId = 4, Code = "ENG 101", Title = "Composition and Rhetoric", Description = "Develop college-level writing skills through essays, research papers, and peer review. Emphasis on argument construction and clear prose.", Credits = 3, Schedule = "Mon/Wed/Fri 9:00–9:50 AM", InstructorName = "Prof. Thomas Grant", InstructorBio = "Prof. Grant is a published author and rhetoric scholar. His essays have appeared in The Atlantic and Harper's Magazine." },
            new() { Id = 11, DepartmentId = 4, Code = "ENG 250", Title = "American Literature", Description = "Survey of American literary works from the colonial period to the present. Explores themes of identity, freedom, and the American experience.", Credits = 3, Schedule = "Tue/Thu 2:00–3:20 PM", InstructorName = "Dr. Rachel Adams", InstructorBio = "Dr. Adams is a specialist in 20th-century American fiction and has published a critically acclaimed study of the Harlem Renaissance." },
            new() { Id = 12, DepartmentId = 5, Code = "HIST 101", Title = "World History to 1500", Description = "Survey of major civilizations, trade networks, and cultural exchanges from antiquity through the late medieval period.", Credits = 3, Schedule = "Mon/Wed/Fri 11:00–11:50 AM", InstructorName = "Dr. Michael Torres", InstructorBio = "Dr. Torres is an archaeologist and historian whose fieldwork spans the Mediterranean and Mesoamerica. He brings artifacts and primary sources into every lecture." },
            new() { Id = 13, DepartmentId = 5, Code = "HIST 205", Title = "Modern European History", Description = "Europe from the Enlightenment to the present. Covers revolutions, industrialization, world wars, and the formation of the European Union.", Credits = 3, Schedule = "Tue/Thu 10:30 AM–12:00 PM", InstructorName = "Prof. Eleanor Hughes", InstructorBio = "Prof. Hughes is a historian of modern Europe with expertise in Franco-German relations. She has been a visiting scholar at the Sorbonne and Humboldt University.", IsFeatured = true },
        };
    }

    public List<Department> GetDepartments() => _departments;

    public Department? GetDepartment(int id) => _departments.FirstOrDefault(d => d.Id == id);

    public List<Course> GetCourses(string? search = null, int? departmentId = null)
    {
        var query = _courses.AsEnumerable();

        if (departmentId.HasValue)
            query = query.Where(c => c.DepartmentId == departmentId.Value);

        if (!string.IsNullOrWhiteSpace(search))
        {
            var term = search.Trim();
            query = query.Where(c =>
                c.Title.Contains(term, StringComparison.OrdinalIgnoreCase) ||
                c.Code.Contains(term, StringComparison.OrdinalIgnoreCase) ||
                c.Description.Contains(term, StringComparison.OrdinalIgnoreCase) ||
                c.InstructorName.Contains(term, StringComparison.OrdinalIgnoreCase));
        }

        return query.ToList();
    }

    public List<Course> GetFeaturedCourses() => _courses.Where(c => c.IsFeatured).ToList();

    public Course? GetCourse(int id) => _courses.FirstOrDefault(c => c.Id == id);

    public List<Course> GetCoursesByDepartment(int departmentId) =>
        _courses.Where(c => c.DepartmentId == departmentId).ToList();

    public bool SubmitEnrollment(EnrollmentRequest request) => true;
}

